input.script:
users = boundary retry 2 {
    return list_users()
} catch err {
    return fail("LIST_FAILED", err.code + ": " + err.message)
}
dates = ["2026-06-15", "2026-06-16", "2026-06-17", "2026-06-18", "2026-06-19"]

all_days = for date in dates {
    day_ms = time.parse(date + "T00:00:00Z")
    per_user = for u in users {
        av = boundary retry 2 {
            return get_availability({ user_id: u.id, date: date })
        } catch err {
            return fail("AVAIL_FAILED", err.code + ": " + err.message)
        }
        return for b in (av.busy if av.busy != null else []) {
            s = b.start if b.start != null else "00:00"
            e = b.end if b.end != null else "23:59"
            s_ms = time.parse(s) if "T" in s else day_ms + number.parse(text.split(s, ":")[0]) * 3600000 + number.parse(text.split(s, ":")[1]) * 60000
            e_ms = time.parse(e) if "T" in e else day_ms + number.parse(text.split(e, ":")[0]) * 3600000 + number.parse(text.split(e, ":")[1]) * 60000
            return { start_ms: s_ms, end_ms: e_ms }
        }
    }
    merged = fold acc = [] for lst in per_user {
        return acc + lst
    }
    return { date: date, day_ms: day_ms, busy: merged }
}

valid = for day in all_days {
    return for m in list.range(540, 961, 30) {
        start_ms = day.day_ms + m * 60000
        end_ms = start_ms + 3600000
        conflict = fold acc = false for b in day.busy {
            return acc or (b.start_ms < end_ms and b.end_ms > start_ms)
        }
        skip if conflict
        return { start_ms: start_ms, end_ms: end_ms }
    }
}
flat = fold acc = [] for v in valid {
    return acc + v
}
sorted = list.sort_by(flat, "start_ms")
first = sorted[0] if sorted != [] else fail("NO_SLOT", "no valid 60-minute slot found in the week")
answer = { start: time.format(first.start_ms), end: time.format(first.end_ms) }
res = submit_result({ answer: answer })
return answer

